package com.example.data.model

/**
 * A country's first-level areas (states, governorates, provinces) for registration step 2's area dropdown. Data:
 * [regionsRaw] (generated by scripts/i18n/build_regions.py). Stored values are the English names; [label] shows them in the
 * app language where a translation exists.
 */
object Regions {
    /** The areas of [isoCode] ("LB"), English names, sorted; empty when the source lists none. */
    fun of(isoCode: String): List<String> = regionsRaw(isoCode.uppercase())?.split('|').orEmpty()

    /** [area] in [language] ("ar") when known, else as stored. */
    fun label(isoCode: String, area: String, language: String): String =
        regionsLocal[language.substringBefore('-').lowercase()]?.get(isoCode.uppercase())?.get(area) ?: area

    /**
     * The list entry a geocoder's area name stands for ("Mount Lebanon Governorate" → "Mount Lebanon", "Beyrouth" stays
     * unmatched), comparing letters only, without case or accents; null when nothing matches.
     */
    fun match(isoCode: String, name: String?): String? {
        val wanted = fold(name ?: return null).ifEmpty { return null }
        val areas = of(isoCode)
        return areas.firstOrNull { fold(it) == wanted }
            ?: areas.firstOrNull { val a = fold(it); a.length >= 4 && (wanted.contains(a) || a.contains(wanted)) }
    }

    private fun fold(text: String): String = buildString {
        for (c in text.lowercase()) {
            val plain = ACCENTS[c] ?: c
            if (plain.isLetterOrDigit()) append(plain)
        }
    }

    private val ACCENTS: Map<Char, Char> = buildMap {
        "àáâãäå" .forEach { put(it, 'a') }; "èéêë".forEach { put(it, 'e') }; "ìíîï".forEach { put(it, 'i') }
        "òóôõö".forEach { put(it, 'o') }; "ùúûü".forEach { put(it, 'u') }; put('ç', 'c'); put('ñ', 'n'); put('ý', 'y')
    }
}
